import {uniquePairs} from './memory-engine.js';
export const DIRECTIONS=[[0,-1],[1,0],[0,1],[-1,0]];
export class MazeGame{
 constructor(pack,{random=Math.random}={}){this.pack=uniquePairs(pack);if(this.pack.length<4)throw Error('異なる訳の単語を4組以上入れてください。');this.random=random;this.player={x:1,y:1};this.enemies=[{x:7,y:1,kind:'patrol'},{x:1,y:7,kind:'chaser'},{x:7,y:7,kind:'patrol'}];this.grid=Array.from({length:9},(_,y)=>Array.from({length:9},(_,x)=>x===0||y===0||x===8||y===8||x%2===0&&y%2===0?1:0));const safe=new Set(['1,1','1,2','2,1','1,3','3,1','3,2','2,3','7,1','1,7','7,7']);for(let y=1;y<8;y++)for(let x=1;x<8;x++)if(!this.grid[y][x]&&!safe.has(x+','+y)&&random()<.38)this.grid[y][x]=2;this.bombs=[];this.flames=[];this.ammo=1;this.hp=3;this.time=150;this.cooldown=0;this.invincible=0;this.enemyClock=0;this.mode='play';this.quiz=null;this.qIndex=0;this.correct=0;this.answered=0;this.destroyed=0;this.kills=0;this.review=new Map();}
 blocked(x,y){return !this.grid[y]||this.grid[y][x]!==0||this.bombs.some(b=>b.x===x&&b.y===y);}
 move(dx,dy){if(this.mode!=='play'||this.quiz||Math.abs(dx)+Math.abs(dy)!==1)return false;this.input=[dx,dy];return true;}
 stop(){this.input=null;}
 canStand(x,y){const r=.27;for(const xx of[x-r,x+r])for(const yy of[y-r,y+r]){const cx=Math.floor(xx+.5),cy=Math.floor(yy+.5);if(this.grid[cy]?.[cx]!==0)return false;if(this.bombs.some(b=>b.x===cx&&b.y===cy&&!b.pass))return false;}return true;}
 advancePlayer(dt){if(!this.input)return;const [dx,dy]=this.input,p=this.player,speed=3.8*dt,axis=dx?'y':'x',center=Math.round(p[axis]);
 // Gently align to corridor centers when a turn is requested near a corner.
 if(Math.abs(p[axis]-center)<.24){const q={...p};q[axis]=center;if(this.canStand(q.x+dx*.3,q.y+dy*.3)){const step=Math.min(speed,Math.abs(center-p[axis]));p[axis]+=Math.sign(center-p[axis])*step;}}
 const x=p.x+dx*speed,y=p.y+dy*speed;if(this.canStand(x,y)){p.x=x;p.y=y;}
 for(const b of this.bombs)if(b.pass&&(Math.abs(p.x-b.x)>.78||Math.abs(p.y-b.y)>.78))b.pass=false;
 }
 place(){const x=Math.round(this.player.x),y=Math.round(this.player.y);if(this.mode!=='play'||this.quiz||this.ammo<1||this.bombs.length>=2||this.bombs.some(b=>b.x===x&&b.y===y))return false;this.ammo--;this.bombs.push({x,y,life:2.4,pass:true});return true;}
 blastCells(b){const cells=[{x:b.x,y:b.y}];for(const[dx,dy]of DIRECTIONS)for(let n=1;n<=2;n++){const x=b.x+dx*n,y=b.y+dy*n;if(this.grid[y]?.[x]===undefined||this.grid[y][x]===1)break;cells.push({x,y});if(this.grid[y][x]===2)break;}return cells;}
 openQuiz(){if(this.mode!=='play'||this.quiz||this.ammo>=4)return false;const target=this.pack[this.qIndex++%this.pack.length],others=this.pack.filter(p=>p!==target);for(let i=others.length-1;i;i--){const j=Math.floor(this.random()*(i+1));[others[i],others[j]]=[others[j],others[i]];}const choices=[target,...others.slice(0,2)];for(let i=choices.length-1;i;i--){const j=Math.floor(this.random()*(i+1));[choices[i],choices[j]]=[choices[j],choices[i]];}this.quiz={target,choices,answered:false,result:null};return true;}
 answerQuiz(index){if(!this.quiz||this.quiz.answered||!Number.isInteger(index)||index<0||index>=3)return null;this.answered++;this.quiz.answered=true;const ok=this.quiz.choices[index]===this.quiz.target;this.quiz.result=ok;if(ok){this.correct++;this.ammo=Math.min(4,this.ammo+2);}else this.review.set(this.quiz.target.word,this.quiz.target);return ok;}
 closeQuiz(){this.quiz=null;}
 explode(b){if(!this.bombs.includes(b))return;this.bombs=this.bombs.filter(a=>a!==b);const cells=this.blastCells(b);for(const c of cells){if(this.grid[c.y][c.x]===2){this.grid[c.y][c.x]=0;this.destroyed++;}this.flames.push({...c,life:.65});}for(const other of [...this.bombs])if(cells.some(c=>c.x===other.x&&c.y===other.y))this.explode(other);}
 check(){if(this.mode!=='play')return;const hit=p=>this.flames.some(f=>Math.abs(f.x-p.x)<.7&&Math.abs(f.y-p.y)<.7);const dead=this.enemies.filter(hit);this.kills+=dead.length;this.enemies=this.enemies.filter(e=>!hit(e));if(this.invincible<=0&&(hit(this.player)||this.enemies.some(e=>Math.hypot(e.x-this.player.x,e.y-this.player.y)<.6))){this.hp--;this.invincible=1.3;if(this.hp<=0)this.mode='lost';}if(this.mode==='play'&&!this.enemies.length&&Math.hypot(this.player.x-7,this.player.y-7)<.35)this.mode='won';}
 advanceEnemies(dt){for(const e of this.enemies){if(!e.target){const choices=DIRECTIONS.filter(([dx,dy])=>!this.blocked(Math.round(e.x)+dx,Math.round(e.y)+dy));if(!choices.length)continue;const safe=choices.filter(([dx,dy])=>!this.bombs.some(b=>b.life<1.4&&this.blastCells(b).some(c=>c.x===Math.round(e.x)+dx&&c.y===Math.round(e.y)+dy)));let pool=safe.length?safe:choices;const forward=pool.filter(([dx,dy])=>!e.previous||dx!==-e.previous[0]||dy!==-e.previous[1]);if(forward.length)pool=forward;if(e.kind==='chaser'&&this.random()<.65)pool=[...pool].sort((a,b)=>Math.hypot(e.x+a[0]-this.player.x,e.y+a[1]-this.player.y)-Math.hypot(e.x+b[0]-this.player.x,e.y+b[1]-this.player.y)).slice(0,1);const [dx,dy]=pool[Math.floor(this.random()*pool.length)];e.previous=[dx,dy];e.target={x:Math.round(e.x)+dx,y:Math.round(e.y)+dy};}const dx=e.target.x-e.x,dy=e.target.y-e.y,d=Math.hypot(dx,dy),step=Math.min(d,1.65*dt);if(d){e.x+=dx/d*step;e.y+=dy/d*step;}if(d<=step+1e-8){e.x=e.target.x;e.y=e.target.y;e.target=null;}}}
 tick(dt){if(this.mode!=='play'||this.quiz||!Number.isFinite(dt)||dt<=0)return;let remaining=Math.min(dt,.1);while(remaining>1e-8&&this.mode==='play'){const step=Math.min(remaining,1/120);remaining-=step;this.time=Math.max(0,this.time-step);if(!this.time){this.mode='lost';break;}this.invincible=Math.max(0,this.invincible-step);this.flames=this.flames.filter(f=>(f.life-=step)>0);for(const b of [...this.bombs]){b.life-=step;if(b.life<=1e-8)this.explode(b);}this.check();if(this.mode!=='play')break;this.advancePlayer(step);this.advanceEnemies(step);this.check();}}
}
